const $ = (s, el = document) => el.querySelector(s);
const $$ = (s, el = document) => [...el.querySelectorAll(s)];
const esc = (v = '') => String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => new Intl.NumberFormat('en-US', {style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const bookmark = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 4h12v16l-6-4-6 4z"/></svg>';
const mark = '<svg viewBox="0 0 100 100" aria-hidden="true"><path d="M15 72h70M22 60a28 28 0 0156 0M35 80h30"/><circle cx="50" cy="50" r="8"/></svg>';
const plate = '<svg viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="28"/><circle cx="50" cy="50" r="21"/><path d="M10 20v60M6 20v20h8V20M88 20v60M82 20v25h6"/></svg>';
const house = '<svg viewBox="0 0 100 100" aria-hidden="true"><path d="M15 75V30h70v45zM27 75V45h20v30M60 45h13v13H60zM12 30h76M20 24h60M16 81h70"/></svg>';
let data, currentPath = '', lastFilter = null, toastTimer, previousChatFocus;
let compared = [];
let saved = [];
try { saved = JSON.parse(localStorage.getItem('swart-plan-v1') || '[]'); if (!Array.isArray(saved)) saved = []; } catch {}
const state = () => { const [path, query = ''] = (location.hash.slice(1) || '/').split('?'); return {path, query:new URLSearchParams(query)}; };
const isSaved = id => saved.includes(id);
const workFor = id => data.works.find(x => x.id === id);
const placeFor = id => data.places.find(x => x.place_id === id);
const allIds = () => new Set([...data.works.map(x => x.id), ...data.places.map(x => x.place_id)]);
const sourceLink = (url, label = 'Official source ') => `<a class="text-link" target="_blank" rel="noopener noreferrer" href="${esc(url)}">${label}</a>`;
const saveButton = (id, inline = false) => `<button class="${inline?'inline-save':'save-button'} ${isSaved(id)?'saved':''}" data-action="save" data-id="${id}" aria-label="${isSaved(id)?'Remove from':'Save to'} your plan" aria-pressed="${isSaved(id)}">${bookmark}</button>`;
function toast(message) { $('#toast').textContent = message; $('#toast').classList.add('visible'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'), 2600); }
function updateSaved() { try { localStorage.setItem('swart-plan-v1', JSON.stringify(saved)); } catch {} $('#plan-count').textContent = saved.length; }
function toggleSave(id) { if (!allIds().has(id)) return; const had=isSaved(id); saved=had?saved.filter(x=>x!==id):[...saved,id]; updateSaved(); $$(`[data-action="save"][data-id="${id}"]`).forEach(el=>{el.classList.toggle('saved',!had);el.setAttribute('aria-pressed',String(!had));el.setAttribute('aria-label',`${had?'Save to':'Remove from'} your plan`);if(el.classList.contains('button'))el.innerHTML=(had?'Save to':'Remove from')+' your plan <span>＋</span>';}); if(state().path==='/plan') render(); toast(had?'Removed from your plan':'Saved to your Taos plan'); }
function artCard(w) { return `<article class="art-card"><a class="art-image" href="#/art/${w.id}" aria-label="Explore ${esc(w.title)}"><img src="assets/${w.image.endsWith('.webp')?w.image.replace('.webp','-card.webp'):w.image}" alt="Original demo image: ${esc(w.title)}" width="420" height="470" loading="lazy"><span class="demo-tag">DEMO WORK</span></a>${saveButton(w.id)}<div class="art-meta"><span class="art-type">${esc(w.medium)}, DEMO COLLECTION</span><div class="art-title-row"><h3><a href="#/art/${w.id}">${esc(w.title)}</a></h3><span aria-hidden="true"></span></div><p>${w.height} × ${w.width} in, example dimensions</p><span class="art-price">Demo price ${money(w.price)}</span><button class="compare-button" data-action="compare" data-id="${w.id}" aria-pressed="${compared.includes(w.id)}">${compared.includes(w.id)?'Selected for comparison ✓':'Compare ＋'}</button></div></article>`; }
function askBand(title='Art questions and filters', prompt='Help me find art I will love') { return `<div class="ask-band"><div><h3>${title}</h3><p>Use the concierge preview to filter the demo collection or ask about Taos.</p></div><button data-action="ask" data-prompt="${esc(prompt)}"><span>Ask Southwest Art</span><span aria-hidden="true">✳ &nbsp; </span></button></div>`; }
function pageLead(eyebrow,title,copy,count='') { return `<div class="page-lead"><div class="breadcrumb"><a href="#/">Southwest Art</a><span>/</span><span>Taos region</span></div><div class="page-lead-row"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${copy}</p></div>${count?`<div class="count-mark">${count}</div>`:''}</div></div>`; }
function placeCard(p, origin = 'plaza') { const price=p.cost===0?'Public access':Number.isFinite(p.cost)?`From ${money(p.cost)} / adult`:'Check current pricing'; return `<article class="place-card"><a href="#/place/${p.place_id}" class="place-image illustration"><img src="assets/${p.type==='Wellness'?'sage-study.webp':'landscape-study.webp'}" alt="Generated desert study. No photograph of ${esc(p.name)}" width="700" height="460" loading="lazy"><span class="demo-tag">ILLUSTRATION, RESEARCH PREVIEW</span></a><span class="locality">${esc(p.type || p.category)}, ${esc(p.locality)}</span><h3><a href="#/place/${p.place_id}">${esc(p.name)}</a></h3><p>${esc(p.original_editorial_brief)}</p><div class="place-facts"><span>${esc(p.duration || 'Time to explore')}</span><strong>${price}</strong></div><p class="travel-note">${esc(p.travelPlanningBands?.[origin]||'Travel to confirm')} from ${origin==='seco'?'Arroyo Seco':'Taos Plaza'}, planning estimate</p><div class="card-bottom"><a class="text-link" href="#/place/${p.place_id}">Take a closer look <span></span></a>${saveButton(p.place_id,true)}</div></article>`; }
function home() { const exp=['harwood-museum-of-art','rio-grande-gorge-overlook-and-west-rim-walk','ojo-caliente-day-soaking'].map(placeFor); return `<section class="hero"><div class="hero-copy"><span class="eyebrow">ART AND VISIT PLANNING, TAOS, NEW MEXICO</span><h1>Art and artists<br>in <em>Taos.</em></h1><p>Explore Taos artists, galleries and places to visit. Save work and stops in your plan.</p><div class="hero-actions"><a class="button" href="#/art">Discover the collection <span></span></a><a class="text-link" href="#/experiences">Explore Taos <span></span></a></div><div class="hero-bottom">TAOS REGION, DESIGN PROTOTYPE</div></div><div class="hero-image"><img src="assets/gallery-hero.webp" alt="Original generated concept of a sunlit adobe gallery, with an abstract painting and desert view" width="1536" height="1024" fetchpriority="high"><span class="hero-tag">OUR FIRST REGION &nbsp; / &nbsp; TAOS</span><div class="image-caption"><strong>Generated gallery concept</strong>Generated gallery concept, Design preview</div></div></section><div class="wrap"><div class="intro-strip"><p>Art research and<br>places to visit</p><div><span class="strip-mark">◌</span><span><strong>Six demo works</strong>Compare medium, size and price.</span></div><div><span class="strip-mark"></span><span><strong>Artist income</strong>Help artists keep living and working here.</span></div></div><section class="section"><div class="section-heading"><div><span class="eyebrow">SELECTED WORKS, PROTOTYPE COLLECTION</span><h2>The demo collection</h2></div><a class="text-link" href="#/art">Explore all work <span></span></a></div><div class="art-grid home-art-grid">${data.works.slice(0,4).map(artCard).join('')}</div>${askBand('Filters for your budget and space','Show abstract works under $5,000')}</section></div><section class="mission-block"><div><span class="eyebrow">THE REASON WE’RE HERE</span><h2>Helping artists sell<br>their work in Taos</h2></div><div class="mission-copy"><p>Our purpose is to help Taos artists earn enough from their work to keep living here. The proposed service connects artists and galleries with buyers through accurate work records, viewings and purchase support.</p><p>The proposal includes free core artist listings and zero platform commission on direct-artist sales. Payment costs need separate funding before production.</p><a href="#/about" class="text-link">Get to know our purpose <span></span></a></div></section><div class="wrap"><section class="section"><div class="section-heading"><div><span class="eyebrow">EXPERIENCES</span><h2>Experiences around Taos</h2></div><a class="text-link" href="#/experiences">Explore experiences <span></span></a></div><div class="experience-grid">${exp.map(p=>placeCard(p)).join('')}</div></section><section class="journal"><div class="journal-image"><img src="assets/landscape-study.webp" width="900" height="600" loading="lazy" alt="Original demo painting of luminous New Mexico hills"></div><div class="journal-copy"><span class="eyebrow">VISIT PLANNING</span><h2>Your Taos visit</h2><p>Save galleries, museums and outdoor stops in one plan. Check opening hours, travel time and access before visiting.</p><a class="text-link" href="#/plan">Start your Taos plan <span></span></a></div></section><section class="section"><div class="section-heading"><div><span class="eyebrow">ARTIST RESEARCH</span><h2>Artist research profiles</h2></div><a class="text-link" href="#/art?tab=artists">Artist profiles <span></span></a></div><div class="artist-grid">${data.artists.slice(0,3).map(artistCard).join('')}</div></section></div>`; }
function artistCard(a) { return `<article class="artist-card"><span class="eyebrow">TAOS REGION, RESEARCH PROFILE</span><span class="artist-number">${String(data.artists.indexOf(a)+1).padStart(2,'0')} /</span><h3><a href="#/artist/${a.id}">${esc(a.artist)}</a></h3><p>${esc(a.curatorial_rationale)}</p><a class="text-link" href="#/artist/${a.id}">Explore profile & sources <span></span></a></article>`; }
function filters() { return state().query; }
function getWorks(q) { let ws=[...data.works]; const search=(q.get('q')||'').toLowerCase(); if(search)ws=ws.filter(w=>[w.title,w.medium,w.palette,w.series].join(' ').toLowerCase().includes(search)); if(q.get('medium'))ws=ws.filter(w=>w.medium===q.get('medium')); if(q.get('palette'))ws=ws.filter(w=>w.palette===q.get('palette')); if(q.get('budget'))ws=ws.filter(w=>w.price<=Number(q.get('budget'))); if(q.get('width'))ws=ws.filter(w=>w.width<=Number(q.get('width'))); if(q.get('sort')==='low')ws.sort((a,b)=>a.price-b.price); if(q.get('sort')==='high')ws.sort((a,b)=>b.price-a.price); if(q.get('sort')==='title')ws.sort((a,b)=>a.title.localeCompare(b.title)); return ws; }
const option=(v,label,selected)=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${label}</option>`;
function artPage(q) { const tab=q.get('tab')||'works',ws=getWorks(q); return `<div class="wrap bottom-space">${pageLead('THE TAOS PERSPECTIVE','Art and artists','Filter six demo works or read profiles of ten Taos artist candidates.')}<div class="tabs"><a href="#/art" class="${tab==='works'?'active':''}">The design collection <small>(6)</small></a><a href="#/art?tab=artists" class="${tab==='artists'?'active':''}">Artist research <small>(10)</small></a></div>${tab==='artists'?`<div class="notice">Each research profile lists six source work records. The project has no seller agreement or image permission for a live offer.</div><div class="artist-grid">${data.artists.map(artistCard).join('')}</div>`:`<div class="filter-bar" id="art-filters"><div class="filter-field search"><label for="art-search">A TITLE, COLOR OR IDEA</label><input id="art-search" data-filter="q" type="search" placeholder="Try ‘blue’ or ‘landscape’" value="${esc(q.get('q')||'')}"></div><div class="filter-field"><label for="art-medium">Medium</label><select id="art-medium" data-filter="medium">${option('','All media',q.get('medium')||'')}${['Painting','Abstract','Sculpture','Digital print'].map(x=>option(x,x,q.get('medium'))).join('')}</select></div><div class="filter-field"><label for="art-budget">Budget</label><select id="art-budget" data-filter="budget">${option('','Any demo price',q.get('budget')||'')}${[1000,3000,5000].map(x=>option(String(x),'Under '+money(x),q.get('budget'))).join('')}</select></div><div class="filter-field"><label for="art-palette">Palette</label><select id="art-palette" data-filter="palette">${option('','Every palette',q.get('palette')||'')}${['Earth','Blue','Green'].map(x=>option(x,x,q.get('palette'))).join('')}</select></div><div class="filter-field"><label for="art-width">Maximum width</label><select id="art-width" data-filter="width">${option('','Any example size',q.get('width')||'')}${[18,30,40].map(x=>option(String(x),x+' inches',q.get('width'))).join('')}</select></div><button class="text-link" data-action="clear-art">Clear filters</button></div><div class="results-meta"><div><span>${ws.length} demo ${ws.length===1?'work':'works'}</span><div class="chip-row">${['q','medium','budget','palette','width'].filter(k=>q.has(k)).map(k=>`<span class="chip">${esc(k==='budget'?'Under '+money(Number(q.get(k))):k==='width'?'Up to '+q.get(k)+' in':q.get(k))}</span>`).join('')}${lastFilter!==null?'<button class="text-link" data-action="undo-filters">Undo concierge filters</button>':''}</div></div><label>Sort <select id="art-sort" data-filter="sort">${[['','Our selection'],['low','Price: low to high'],['high','Price: high to low'],['title','Title A–Z']].map(([v,l])=>option(v,l,q.get('sort')||'')).join('')}</select></label></div><div class="notice"><strong>A collection for design review.</strong> The demo collection uses generated images and fictional sizes and prices. It offers no physical artwork for sale.</div>${ws.length?`<div class="art-grid">${ws.map(artCard).join('')}</div>`:`<div class="empty"><h2>No works match these filters</h2><p>No demo works match every filter. Try a different medium, a wider size range or a different budget.</p><button class="button" data-action="clear-art">Clear filters </button></div>`}`}${askBand('Art questions and filters','Show abstract works under $5,000')}</div>`; }
function workPage(w) { if(!w)return notFound(); return `<div class="wrap bottom-space"><div class="page-lead"><div class="breadcrumb"><a href="#/">Southwest Art</a><span>/</span><a href="#/art">The design collection</a><span>/</span><span>${esc(w.title)}</span></div></div><section class="catalog-detail"><div class="large-work"><img src="assets/${w.image}" alt="Original generated or digital demo work: ${esc(w.title)}" width="700" height="850"><button class="zoom-button" data-action="zoom" data-id="${w.id}">A closer look </button></div><div class="object-copy"><span class="eyebrow">SOUTHWEST ART, DEMO COLLECTION</span><h1>${esc(w.title)}</h1><p class="muted">${esc(w.series)}, Original demonstration imagery</p><div class="object-price"><small>DEMO PRICE</small>${money(w.price)}</div><dl class="facts-table"><div><dt>Medium / preview category</dt><dd>${esc(w.medium)}</dd></div><div><dt>Example dimensions</dt><dd>${w.height} H × ${w.width} W in</dd></div><div><dt>Presentation</dt><dd>${esc(w.orientation)} study</dd></div><div><dt>Availability</dt><dd>Demo. No physical artwork for sale</dd></div></dl><div class="object-actions"><button class="button" data-action="checkout" data-id="${w.id}">Preview purchase <span></span></button><button class="button secondary" data-action="viewing" data-id="${w.id}">Request a viewing, demo <span></span></button><button class="button secondary" data-action="save" data-id="${w.id}" aria-pressed="${isSaved(w.id)}">${isSaved(w.id)?'Remove from':'Save to'} your plan <span>＋</span></button></div><p class="small-print">The prototype uses a generated image and fictional work details. It offers no physical artwork. Checkout and viewing requests demonstrate the process without taking payment or sending messages.</p></div></section><section class="detail-story"><h2>About this demo study</h2><p>This study lets you explore the whole-image presentation, scale information, comparison and purchase flow. In a live catalog, this space will hold an approved artist account, exact object information, condition, representation and a clear delivery quote.</p></section>${askBand('Size, palette and budget questions','Find a green abstract work under $4,000')}</div>`; }
function artistPage(a) { if(!a)return notFound();return `<div class="wrap bottom-space">${pageLead('ARTIST RESEARCH, TAOS REGION',esc(a.artist),esc(a.curatorial_rationale))}<div class="notice"><strong>Artist research preview</strong> The project has no participation agreement, image rights, seller authority or stock confirmation. Check each of the six source records with the actual seller.</div><section class="detail-story"><h2>Sources and stock limitations</h2><div><p>${esc(a.sourcing_limitations)}</p>${sourceLink(a.context_source_url,'Artist / context source ')}</div></section><div class="work-source-list">${a.works.map(w=>`<article class="source-work"><div><span class="art-type">SOURCED WORK, ${esc(w.artwork_year||'YEAR NOT SUPPLIED')}</span><h3>${esc(w.title)}</h3><p>${esc(w.medium)}</p></div><div><p>${esc(w.dimensions_as_published)} ${w.dimension_unit==='in'?'in':', unit unknown'}</p><p>${esc(w.source_seller)}</p>${sourceLink(w.source_url,'View source record ')}</div><div class="source-price">${w.price_usd?money(Number(w.price_usd)):'Price not published'}<small>Source asking price<br>Availability unconfirmed</small></div></article>`).join('')}</div>${askBand('Questions before you collect?','How do I know a work is available?')}</div>`; }
function galleriesPage() { const gs=data.places.filter(x=>x.category==='gallery');return `<div class="wrap bottom-space">${pageLead('GALLERIES, MANY PERSPECTIVES','Taos galleries','Twelve gallery candidates with source links and visiting details to confirm.','12<small>Gallery candidates</small>')}<div class="gallery-spotlight"><div class="image-block"><img src="assets/gallery-hero.webp" alt="Generated gallery concept. It does not depict HOUSE of FIRE" width="900" height="600"><span class="demo-tag">GENERATED GALLERY CONCEPT</span></div><div class="spotlight-copy"><span class="eyebrow">GALLERY RESEARCH</span><h2>HOUSE of FIRE</h2><p>Contemporary art on Kit Carson Road. Gallery Director: Felix Kay. Exhibition details and visiting arrangements require confirmation with the gallery.</p><a class="text-link" href="#/place/house-of-fire">Explore the research preview <span></span></a></div></div><div class="notice">The project has no paid agreement with these twelve gallery candidates. Production profiles must identify paid services.</div>${gs.map((p,i)=>`<article class="gallery-row"><span class="row-number">${String(i+1).padStart(2,'0')}</span><div><span class="locality">${esc(p.locality)}</span><h3><a href="#/place/${p.place_id}">${esc(p.name)}</a></h3></div><p>${esc(p.original_editorial_brief)}</p><div class="row-actions"><a class="text-link" href="#/place/${p.place_id}">Explore <span></span></a>${saveButton(p.place_id,true)}</div></article>`).join('')}${askBand('Gallery questions','Help me choose galleries to visit')}</div>`; }
function mapPanel() { return `<div class="map-panel"><span class="eyebrow">A SENSE OF PLACE</span><svg viewBox="0 0 450 550" role="img" aria-label="Schematic of Taos, Arroyo Seco, Taos Ski Valley, the Rio Grande Gorge and Ojo Caliente. No scale or navigation"><path class="mountain" d="M290 125l35-80 30 60 30-38 45 90M300 148l30-55 20 40 45-21 35 55M285 190l40-45 32 35 40-36 35 66"/><path class="river" d="M110 30c60 90-60 110-15 190s-15 140-45 200"/><path class="map-road" d="M230 485V305Q235 250 235 207T263 154L335 105M230 305L102 230M230 350L90 455"/><g><circle class="point" cx="230" cy="305" r="8"/><text x="245" y="310">Taos town</text><circle class="point" cx="263" cy="154" r="8"/><text x="158" y="143">Arroyo Seco</text><circle class="point" cx="335" cy="105" r="8"/><text x="248" y="80">Taos Ski Valley</text><circle class="point" cx="102" cy="230" r="8"/><text x="20" y="210">Rio Grande Gorge</text><circle class="point" cx="90" cy="455" r="8"/><text x="105" y="460">Ojo Caliente</text><circle class="point" cx="242" cy="255" r="8"/><text x="260" y="260">Taos Pueblo</text></g></svg><p>Regional schematic. It provides no scale or navigation. Confirm the actual entrance, route, weather and opening before a visit.</p></div>`; }
function experiencesPage(q) { let ps=data.places.filter(x=>x.category==='experience');if(q.get('type'))ps=ps.filter(p=>p.type===q.get('type'));if(q.get('time'))ps=ps.filter(p=>p.minutes<=Number(q.get('time')));if(q.get('cost')==='free')ps=ps.filter(p=>p.cost===0);if(q.get('cost')==='25')ps=ps.filter(p=>p.cost!==null&&p.cost<=25);if(q.get('sort')==='cost')ps.sort((a,b)=>(a.cost??1e6)-(b.cost??1e6));const map=q.get('view')==='map';return `<div class="wrap bottom-space">${pageLead('EXPERIENCES, MAKE TIME FOR TAOS','Taos experiences','Compare ten museums, heritage visits, outdoor activities and soaking options.')}<div class="filter-bar" id="place-filters"><div class="filter-field"><label for="experience-origin">Starting from</label><select id="experience-origin" data-exp-filter="origin">${option('','Taos Plaza',q.get('origin')||'')}${option('seco','Arroyo Seco',q.get('origin'))}</select></div><div class="filter-field"><label for="experience-type">Your kind of day</label><select id="experience-type" data-exp-filter="type">${option('','All experiences',q.get('type')||'')}${['Art & culture','Heritage','Outdoors','Adventure','Wellness'].map(x=>option(x,x,q.get('type'))).join('')}</select></div><div class="filter-field"><label for="experience-time">Time to explore</label><select id="experience-time" data-exp-filter="time">${option('','Any duration',q.get('time')||'')}${option('120','Up to 2 hours',q.get('time'))}${option('240','Half-day or less',q.get('time'))}</select></div><div class="filter-field"><label for="experience-cost">Price</label><select id="experience-cost" data-exp-filter="cost">${option('','Any price',q.get('cost')||'')}${option('free','Public-access choices',q.get('cost'))}${option('25','Up to $25 / adult',q.get('cost'))}</select></div><div class="filter-field"><label for="experience-sort">Sort</label><select id="experience-sort" data-exp-filter="sort">${option('','Our selection',q.get('sort')||'')}${option('cost','Published cost',q.get('sort'))}</select></div><div class="view-toggle"><button data-action="view-list" class="${!map?'active':''}">List</button><button data-action="view-map" class="${map?'active':''}">Map</button></div></div><div class="results-meta"><span>${ps.length} selected ${ps.length===1?'experience':'experiences'}, provider facts checked October 19, 2026</span><button data-action="clear-experiences">Clear filters</button></div><div class="notice">Prices come from published sources and need date-specific confirmation. Check seasonal operations and access. The images show generated concepts. Travel bands are manual estimates. The project has no referral agreements.</div>${ps.length?`<div class="${map?'map-layout':'experience-grid'}">${map?mapPanel():''}<div class="${map?'map-list':'experience-grid-inner'}" ${map?'':'style="display:contents"'}>${ps.map(p=>placeCard(p,q.get('origin')||'plaza')).join('')}</div></div>`:'<div class="empty"><h2>No experiences match these filters</h2><p>Try removing a filter to see more of the region.</p><button class="button" data-action="clear-experiences">See every experience </button></div>'}${askBand('Questions about your Taos visit','Plan an art afternoon from Arroyo Seco')}</div>`; }
function hospitalityPage(q) { const tab=q.get('tab')==='stay'?'stay':'eat',cat=tab==='stay'?'lodging':'restaurant';let ps=data.places.filter(x=>x.category===cat);if(q.get('area')==='north')ps=ps.filter(p=>/seco|prado|north|ski valley/i.test(p.locality));return `<div class="wrap bottom-space">${pageLead('EAT & STAY, PART OF A GOOD VISIT',tab==='stay'?'Places to stay':'Taos restaurants',tab==='stay'?'Compare eight lodging candidates by location, room type and published facilities.':'Eight restaurant candidates in Taos, Arroyo Seco and the surrounding area.')}<div class="tabs"><a href="#/eat-stay" class="${tab==='eat'?'active':''}">Eat <small>(8)</small></a><a href="#/eat-stay?tab=stay" class="${tab==='stay'?'active':''}">Stay <small>(8)</small></a></div><div class="filter-bar"><div class="filter-field"><label for="hospitality-area">Location</label><select id="hospitality-area" data-hosp-filter="area">${option('','All Taos region',q.get('area')||'')}${option('north','Seco / north / mountain',q.get('area'))}</select></div><span class="muted" style="font-size:11px;margin-left:auto">${ps.length} researched choices</span></div><div class="notice">These businesses remain candidates for paid profiles. None has agreed to participate. ${tab==='stay'?'The prototype has no live room rates or availability.':'Confirm current dishes and prices with the restaurant.'} Production profiles must label paid services.</div><div class="hospitality-grid">${ps.map(p=>`<article class="hospitality-card"><div class="hospitality-graphic">${tab==='stay'?house:plate}</div><span class="locality">${esc(p.locality)}</span><h3><a href="#/place/${p.place_id}">${esc(p.name)}</a></h3><p>${esc(p.original_editorial_brief)}</p><div class="mini-fact">${esc(tab==='stay'?p.type||'Distinctive stay':p.type||'Local dining')}, ${esc(tab==='stay'?'Check rates for your dates':p.range||'See current menu')}</div><div class="card-bottom"><a class="text-link" href="#/place/${p.place_id}">Explore ${tab==='stay'?'the stay':'the table'} <span></span></a>${saveButton(p.place_id,true)}</div></article>`).join('')}</div>${askBand(tab==='stay'?'Lodging questions':'Restaurant questions',tab==='stay'?'Find a place to stay near Arroyo Seco':'Where can I have dinner in Arroyo Seco?')}</div>`; }
function placePage(p) { if(!p)return notFound();const exp=p.category==='experience',gallery=p.category==='gallery',stay=p.category==='lodging';const back=exp?'experiences':gallery?'galleries':'eat-stay';return `<div class="wrap bottom-space"><div class="page-lead"><div class="breadcrumb"><a href="#/">Southwest Art</a><span>/</span><a href="#/${back}${stay?'?tab=stay':''}">${exp?'Experiences':gallery?'Galleries':stay?'Stay':'Eat'}</a><span>/</span><span>${esc(p.name)}</span></div></div><section class="place-detail-hero"><div class="place-detail-art">${exp||gallery?`<img src="assets/${exp?'landscape-study.webp':'gallery-hero.webp'}" alt="Generated concept. No photograph of ${esc(p.name)}" width="800" height="650"><span class="demo-tag">GENERATED SCENE</span>`:`<div class="abstract-venue">${stay?house:plate}</div>`}</div><div class="place-detail-copy"><span class="eyebrow">${esc(p.type||p.category)}, RESEARCH PREVIEW</span><h1>${esc(p.name)}</h1><span class="locality">${esc(p.locality)}</span><p style="margin-top:22px">${esc(p.original_editorial_brief)}</p>${exp?`<dl class="facts-table"><div><dt>Time to allow</dt><dd>${esc(p.duration)}</dd></div><div><dt>Best time</dt><dd>${esc(p.time)}</dd></div><div><dt>Price basis</dt><dd>${esc(p.published_price_basis||'Confirm with provider')}</dd></div><div><dt>Practical detail</dt><dd>${esc(p.effort)}</dd></div></dl>`:`<p class="price-state">${stay?'Check rates for your dates':gallery?'Current work and viewings require confirmation':esc(p.range||'Check the current menu')}</p>`}<p class="small-print">${esc(p.notes)}</p>${stay?`<div class="room-list">${(p.rooms||['Ask the property about its current room options']).map(r=>`<div><span>${esc(r)}</span><small>Request current quote</small></div>`).join('')}</div><div class="date-fields"><label>Arrival<input type="date" id="stay-arrival" min="2026-11-01"></label><label>Departure<input type="date" id="stay-departure" min="2026-11-02"></label></div><button class="button full" style="margin-top:15px" data-action="rate-help" data-id="${p.place_id}">Check the booking next step <span></span></button>`:''}<div style="display:flex;gap:20px;align-items:center;margin-top:22px;flex-wrap:wrap">${sourceLink(p.source_url,exp?'Visit the official provider ':stay?'Visit property website ':gallery?'Gallery / source information ':'Visit menu / official source ')}<button class="button secondary small" data-action="save" data-id="${p.place_id}" aria-pressed="${isSaved(p.place_id)}">${isSaved(p.place_id)?'Remove from':'Save to'} your plan <span>＋</span></button></div></div></section><div class="notice" style="margin-top:35px">Published/source-checked October 19, 2026. Reconfirm current facts before a visit. The project has no participation or booking agreement. The provider fulfills its own services. The project assumes no referral commission.</div>${askBand('A little more context makes a better visit.',exp?'Plan an art afternoon from Arroyo Seco':stay?'Compare places to stay':'Help me plan a gallery visit')}</div>`; }
function planPage(q) { const shared=q.get('items');if(shared){saved=[...new Set([...saved,...shared.split(',').filter(id=>allIds().has(id))])].slice(0,50);updateSaved();history.replaceState(null,'',location.pathname+'#/plan');}return `<div class="wrap bottom-space">${pageLead('YOUR TAOS PLAN','Your saved Taos plan','Save demo work and places, change their order, and share or download your selections.')} ${saved.length?`<div class="plan-layout"><div class="plan-list">${saved.map((id,i)=>{const w=workFor(id),p=placeFor(id),name=w?.title||p?.name;if(!name)return '';return `<article class="plan-item"><a class="plan-thumb" href="#/${w?'art':'place'}/${id}">${w?`<img src="assets/${w.image}" alt="Demo ${esc(name)}" width="85" height="90">`:mark}</a><div><span class="art-type">${w?'DEMO WORK':esc(p.category)+', RESEARCH'}</span><h3><a href="#/${w?'art':'place'}/${id}">${esc(name)}</a></h3><p>${w?'Demo price '+money(w.price):esc(p.locality)}</p></div><div class="plan-controls"><button data-action="move-up" data-id="${id}" ${i===0?'disabled':''} aria-label="Move ${esc(name)} earlier">Move up </button><button data-action="save" data-id="${id}" aria-label="Remove ${esc(name)} from plan">Remove ×</button></div></article>`}).join('')}</div><aside class="plan-summary"><span class="eyebrow">SAVED TAOS SELECTIONS</span><h2 style="margin-top:15px">Saved selections</h2><p>${saved.length} saved ${saved.length===1?'selection':'selections'}. This browser stores your shortlist. It creates no appointments or reservations.</p><button class="button full" data-action="share-plan">Copy a shareable shortlist <span></span></button><button class="button secondary full" data-action="download-plan">Download your selections <span></span></button><button class="text-link" data-action="plan-help">Talk through the plan <span>✳</span></button><p class="small-print">You need no account. The shortlist contains only public work and place IDs. Travel times, access and bookings need confirmation.</p></aside></div>`:`<div class="empty"><span class="eyebrow" style="margin-bottom:22px">NO SAVED SELECTIONS</span><h2>Your plan is empty</h2><p>Use the bookmark on a work, gallery or experience. Your selections will be waiting here.</p><a class="button" href="#/art">Find your first favorite <span></span></a></div>`}${askBand('Questions about your plan','Plan an art afternoon from Arroyo Seco')}</div>`; }
function aboutPage(buy=false) { return `<div class="wrap"><article class="prose"><span class="eyebrow">${buy?'A CAREFUL WAY TO COLLECT':'THE REASON WE’RE HERE'}</span><h1>${buy?'Buying art':'Purpose and artist terms'}</h1>${buy?`<p>The proposed buying service provides work details, seller terms, viewing options and delivery support. This prototype demonstrates the process. Production selling needs separate review and approval.</p><div class="steps">${[['01 / DISCOVER','Artwork details','Explore real work, exact medium and edition details, dimensions and a clear price or inquiry route.'],['02 / UNDERSTAND','Questions and viewings','Get verified context, detail images, a remote viewing and a real person when you need one.'],['03 / CONFIRM','Seller and full cost','Confirm seller, stock, condition, tax, packing, insured delivery and return terms before payment.'],['04 / ENJOY','Delivery and settlement','Follow the work through safe delivery and artist settlement, with an accountable support contact.']].map(([n,t,p])=>`<div class="step"><span class="eyebrow">${n}</span><h3>${t}</h3><p>${p}</p></div>`).join('')}</div><h2>Artist commission and processing costs</h2><p>The intended direct-artist model has no Southwest Art sales commission. Full-art-price payout needs separate funding for payment costs. Confirm that funding before promising the payout. Gallery, estate and resale arrangements remain distinct.</p>`:`<p>Our purpose is to help artists sell enough work to keep living and working in Taos.</p><p>The proposed service combines art information, seller contacts and practical visit planning. It should serve remote collectors and first buyers with the same factual care.</p><h2>Selection and paid services</h2><p>Artists and businesses in the research previews are candidates for future participation. Their inclusion does not imply a partnership or endorsement.</p><p>The proposal keeps core artist discovery free. Label paid business profiles and keep editorial selection independent of payment.</p><h2>Prototype status</h2><p>The prototype uses generated images and fictional demo prices. It simulates assistance, inquiries and checkout. It accepts no payment or reservation and offers no named artist work for sale.</p><p>Project day one is November 1, 2026. This early preview supports design review before a production decision. Southwest Art remains a working name and is not affiliated with Southwest Art Magazine.</p>`}<a class="button" href="#/art">Return to the collection <span></span></a></article></div>`; }
function notFound() { return '<div class="page-error"><h1>Page not found</h1><p><a href="#/">Return to the Taos perspective </a></p></div>'; }
function render() { if(!data)return;const {path,query}=state();const focused=document.activeElement?.id,scroll=window.scrollY,changed=path!==currentPath;let html,title='Southwest Art ,  Taos';if(path==='/'){html=home();}else if(path==='/art'){html=artPage(query);title='Art & artists ,  Southwest Art';}else if(path.startsWith('/art/')){const w=workFor(path.split('/')[2]);html=workPage(w);title=(w?.title||'Work')+' ,  Southwest Art';}else if(path.startsWith('/artist/')){const a=data.artists.find(x=>x.id===path.split('/')[2]);html=artistPage(a);title=(a?.artist||'Artist')+' ,  Southwest Art';}else if(path==='/galleries'){html=galleriesPage();title='Taos galleries ,  Southwest Art';}else if(path==='/experiences'){html=experiencesPage(query);title='Taos experiences ,  Southwest Art';}else if(path==='/eat-stay'){html=hospitalityPage(query);title='Eat & stay ,  Southwest Art';}else if(path.startsWith('/place/')){const p=placeFor(path.split('/')[2]);html=placePage(p);title=(p?.name||'Place')+' ,  Southwest Art';}else if(path==='/plan'){html=planPage(query);title='Your Taos plan ,  Southwest Art';}else if(path==='/about'||path==='/how-to-buy'){html=aboutPage(path==='/how-to-buy');}else html=notFound();$('#main').innerHTML=html;document.title=title;$$('[data-nav]').forEach(el=>el.classList.toggle('active',path.includes(el.dataset.nav)));$('#mobile-nav').hidden=true;$('#menu-button').setAttribute('aria-expanded','false');currentPath=path;updateSaved();if(changed){window.scrollTo(0,0);}else{window.scrollTo(0,scroll);if(focused){const el=document.getElementById(focused);el?.focus({preventScroll:true});if(el instanceof HTMLInputElement&&el.type==='search')el.setSelectionRange(el.value.length,el.value.length);}} }
function modal(content,zoom=false) { const d=$('#modal');if(d.open)d.close();d.classList.toggle('zoom-modal',zoom);$('#modal-content').innerHTML=content;d.showModal(); }
function previewInfo(){modal('<span class="eyebrow">PROTOTYPE DESIGN REVIEW</span><h2>Welcome to the prototype.</h2><p>Explore the Taos perspective, try filters, meet the researched artist candidates, save a plan and walk through a demonstration purchase.</p><p>The demo collection uses generated images and fictional prices. Named artists and venues remain research candidates without participation agreements. Concierge responses and checkout are simulated. The prototype makes no purchase, booking or message.</p><p>Design review only. Project day one: November 1, 2026. Audo Copenhagen #11 remains the provisional reference. Final design and production need review.</p><button class="button" data-action="close-modal">Let’s take a look <span></span></button>');}
function checkout(w) {modal(`<span class="eyebrow">DEMONSTRATION CHECKOUT, NO PAYMENT</span><h2>Purchase demonstration</h2><div class="checkout-item"><img src="assets/${w.image}" alt="Generated ${esc(w.title)}"><div><h3>${esc(w.title)}</h3><p>Demo collection, ${w.height} × ${w.width} in</p></div></div><form id="checkout-form" data-id="${w.id}"><label for="delivery">Delivery preview<select id="delivery"><option value="0">Collection in Taos, demo $0</option><option value="200">Insured domestic delivery, demo $200</option></select></label><div class="checkout-total"><div><span>Artwork subtotal in this demo</span><span>${money(w.price)}</span></div><div><span>Demo delivery</span><span id="shipping-value">$0</span></div><div><span>Tax</span><span>Not calculated</span></div><div class="sum"><span>Demo total before tax</span><span id="checkout-total">${money(w.price)}</span></div></div><p class="small-print">Example amounts only. A live order will require a confirmed seller, actual inventory and a complete tax/delivery quote. The demo uses no Stripe account or card entry.</p><label class="check-label"><input type="checkbox" id="demo-confirm" required><span>I understand this is a simulation. There is no purchase, reservation or charge.</span></label><button class="button full" type="submit">Complete the demonstration <span></span></button></form>`); }
function viewing(w){modal(`<span class="eyebrow">VIEWING REQUEST, DEMONSTRATION</span><h2>Viewing request demonstration</h2><p>Try the request flow for <strong>${esc(w.title)}</strong>. This demo will not send a message or save your contact details.</p><form id="viewing-form"><label for="viewing-name">Name<input id="viewing-name" type="text" placeholder="Use a demo name" required maxlength="100"></label><label for="viewing-email">Email<input id="viewing-email" type="email" placeholder="demo@example.com" required maxlength="150"></label><label for="viewing-message">What would you like to know?<textarea id="viewing-message" maxlength="1000" placeholder="Scale, materials, a remote viewing…"></textarea></label><button class="button full">Preview the request <span></span></button></form>`);}
function changeQuery(key,value,base=state().path){const q=state().query;if(value)q.set(key,value);else q.delete(key);location.hash=base+(q.size?'?'+q.toString():'');}
function contextPrompts(){const p=state().path;return p.includes('experiences')||p.includes('/place/')?['An art afternoon from Arroyo Seco','A short museum visit','Time for a soak']:p.includes('eat-stay')?['Dinner in Arroyo Seco','Compare places to stay','Build my visit plan']:p.includes('galleries')?['Choose galleries to visit','How do viewings work?','Where should I begin?']:['Abstract under $5,000','Find green work','How does buying work?'];}
function chatMessage(text,role='assistant',action=''){const d=document.createElement('div');d.className='chat-message '+role;d.innerHTML=esc(text).replace(/\n/g,'<br>')+action;$('#chat-messages').append(d);$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight;}
function openChat(prompt=''){if(!data)return;previousChatFocus=document.activeElement;$('#concierge').hidden=false;$('#concierge-launch').hidden=true;['#main','.site-footer','.site-header','.preview-bar'].forEach(s=>$(s).inert=true);$('#chat-prompts').innerHTML=contextPrompts().map(x=>`<button data-action="chat-prompt" data-prompt="${esc(x)}">${esc(x)}</button>`).join('');if(!$('#chat-messages').children.length)chatMessage('Welcome. What would you like to discover? I can demonstrate an art shortlist, visible filters or a thoughtful Taos visit. This preview uses fixed prototype records, with no live inventory or bookings.');$('#chat-input').focus();if(prompt)answer(prompt);}
function closeChat(){$('#concierge').hidden=true;$('#concierge-launch').hidden=false;['#main','.site-footer','.site-header','.preview-bar'].forEach(s=>$(s).inert=false);if(previousChatFocus?.isConnected)previousChatFocus.focus({preventScroll:true});else $('#concierge-launch').focus({preventScroll:true});}
function answer(raw){const text=raw.trim();if(!text)return;chatMessage(text,'user');const q=text.toLowerCase();const budgetMatch=q.match(/(?:under|below|up to|less than)\s*\$?([\d,]+)\s*(k)?/);const budget=budgetMatch?Number(budgetMatch[1].replaceAll(',',''))*(budgetMatch[2]?1000:1):null;if(q.includes('abstract')||q.includes('green')||q.includes('blue')||budget||/sort|cheapest|expensive/.test(q)){const f=new URLSearchParams();if(q.includes('abstract'))f.set('medium','Abstract');if(q.includes('green'))f.set('palette','Green');else if(q.includes('blue'))f.set('palette','Blue');if(budget)f.set('budget',String(budget));if(/sort|cheapest|expensive/.test(q))f.set('sort',/expensive|high|descending/.test(q)?'high':'low');const ws=getWorks(f);const payload=esc(f.toString());chatMessage(ws.length?`I found ${ws.length} demo ${ws.length===1?'work':'works'} matching those constraints:\n${ws.map(w=>w.title+' ,  demo '+money(w.price)).join('\n')}\nThese are demonstration studies, not live art offers.`:'No demo works match every constraint. I can show the empty result honestly, or you can change the budget or palette.','assistant',`<button class="chat-action" data-action="apply-chat-filters" data-query="${payload}">Apply these filters </button>`);}else if(/dinner|restaurant|eat|food/.test(q)){chatMessage('ACEQ is the researched Arroyo Seco candidate. Its published menu has example plates, but current dishes and reservations need the restaurant’s confirmation. Nothing is booked through this prototype.','assistant','<a class="chat-action" href="#/place/aceq" data-action="chat-follow">Explore ACEQ </a>');}else if(/stay|hotel|room|lodging/.test(q)){chatMessage('Hotel Willa is a town candidate with an art program. The Blake is a mountain candidate in Taos Ski Valley. Their current rates depend on dates and room type. I cannot invent a room quote or availability.','assistant','<a class="chat-action" href="#/eat-stay?tab=stay" data-action="chat-follow">Compare the researched stays </a>');}else if(/soak|sauna|spa|cold|plunge/.test(q)){chatMessage('Ojo Caliente’s source lists day soaking with sauna and steam. The retrieved source still describes its new cold plunge as under construction. Check current operations and pricing with the provider before going.','assistant','<a class="chat-action" href="#/place/ojo-caliente-day-soaking" data-action="chat-follow">Explore the soaking preview </a>');}else if(/gallery|galleries|viewing/.test(q)){chatMessage('Start with the program that interests you. HOUSE of FIRE is on Kit Carson Road. 203 Fine Art focuses on modern and contemporary art. A real viewing requires confirmation with the actual gallery.','assistant','<a class="chat-action" href="#/galleries" data-action="chat-follow">Explore gallery candidates </a>');}else if(/afternoon|museum|seco|plan|visit|short/.test(q)){chatMessage('A possible art afternoon from Arroyo Seco: travel to town, allow 1–2 hours at Harwood, then a confirmed nearby gallery viewing with a break in between. Harwood’s source lists Wed–Sun hours and a March 2027 closure. Check actual travel times and confirm visits before using this plan.','assistant','<a class="chat-action" href="#/place/harwood-museum-of-art" data-action="chat-follow">Explore Harwood </a>');}else if(/available|availability|buy|purchase|collect|how/.test(q)){chatMessage('For real work, first confirm the seller, current availability, medium/edition, exact size, price, condition, delivery and return terms. This prototype has no live sale offers. Its example checkout cannot take money.','assistant','<a class="chat-action" href="#/how-to-buy" data-action="chat-follow">See the collecting journey </a>');}else{chatMessage('I can demonstrate filtering by medium, palette or demo budget, compare the researched places, and explain the buying journey. Try “abstract under $5,000” or “an art afternoon from Arroyo Seco.” For other questions, a live service would use verified records and an informed human handoff.');}}
let inputTimer;
document.addEventListener('input',e=>{if(e.target.matches('[data-filter="q"]')){clearTimeout(inputTimer);const value=e.target.value;inputTimer=setTimeout(()=>changeQuery('q',value,'/art'),300);}});
document.addEventListener('change',e=>{const t=e.target;if(t.matches('[data-filter]')&&t.dataset.filter!=='q')changeQuery(t.dataset.filter,t.value,'/art');if(t.matches('[data-exp-filter]'))changeQuery(t.dataset.expFilter,t.value,'/experiences');if(t.matches('[data-hosp-filter]'))changeQuery(t.dataset.hospFilter,t.value,'/eat-stay');if(t.id==='delivery'){const w=workFor($('#checkout-form').dataset.id);$('#shipping-value').textContent=money(Number(t.value));$('#checkout-total').textContent=money(w.price+Number(t.value));}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(a==='compare')compareWork(id);if(a==='save')toggleSave(id);if(a==='clear-art'){lastFilter=null;location.hash='/art';}if(a==='clear-experiences')location.hash='/experiences';if(a==='view-map')changeQuery('view','map','/experiences');if(a==='view-list')changeQuery('view','','/experiences');if(a==='ask')openChat(b.dataset.prompt);if(a==='chat-prompt')answer(b.dataset.prompt);if(a==='chat-follow')closeChat();if(a==='apply-chat-filters'){lastFilter=state().path==='/art'?state().query.toString():'';closeChat();location.hash='/art?'+b.dataset.query;toast('Filters applied to the design collection');}if(a==='undo-filters'){location.hash='/art'+(lastFilter?'?'+lastFilter:'');lastFilter=null;}if(a==='checkout')checkout(workFor(id));if(a==='viewing')viewing(workFor(id));if(a==='zoom'){const w=workFor(id);modal(`<span class="eyebrow" style="margin-bottom:20px">DEMO, ${esc(w.title)}</span><img src="assets/${w.image}" alt="Enlarged demonstration artwork: ${esc(w.title)}">`,true);}if(a==='close-modal')$('#modal').close();if(a==='preview-info')previewInfo();if(a==='move-up'){const i=saved.indexOf(id);if(i>0){[saved[i-1],saved[i]]=[saved[i],saved[i-1]];updateSaved();render();}}if(a==='share-plan'){const link=location.origin+location.pathname+'#/plan?items='+encodeURIComponent(saved.join(','));try{await navigator.clipboard.writeText(link);toast('Shareable shortlist copied');}catch{modal(`<span class="eyebrow">SHARE YOUR SHORTLIST</span><h2>Your shortlist link</h2><p>Copy this link. It contains only the selected work/place IDs, no personal details.</p><input type="text" readonly value="${esc(link)}" aria-label="Shareable shortlist URL">`);}}if(a==='download-plan'){const body='YOUR SOUTHWEST ART SHORTLIST\nDesign prototype ,  no confirmed bookings or purchases.\n\n'+saved.map(id=>{const x=workFor(id)||placeFor(id);return (x.title||x.name)+(x.locality?' ,  '+x.locality:' ,  demo work');}).join('\n')+'\n\nConfirm real availability, hours, access and delivery before acting.';const url=URL.createObjectURL(new Blob([body],{type:'text/plain'}));const link=document.createElement('a');link.href=url;link.download='my-taos-shortlist.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}if(a==='plan-help')openChat('Plan an art afternoon from Arroyo Seco');if(a==='rate-help'){const start=$('#stay-arrival').value,end=$('#stay-departure').value;if(!start||!end||end<=start){toast('Choose an arrival and a later departure date');return;}const p=placeFor(id);modal(`<span class="eyebrow">A REAL QUOTE NEEDS YOUR DATES</span><h2>Room quote from ${esc(p.name)}</h2><p>Your selected dates: ${esc(start)} to ${esc(end)}. This prototype has no live room inventory or booking agreement. The property must confirm the room, total rate, taxes/fees and cancellation terms.</p>${sourceLink(p.source_url,'Continue to the official property site ')}<p class="small-print">The prototype creates no reservation and sends no dates to the property.</p>`);}});
document.addEventListener('submit',e=>{if(e.target.id==='chat-form'){e.preventDefault();const q=$('#chat-input').value;$('#chat-input').value='';answer(q);}if(e.target.id==='checkout-form'){e.preventDefault();modal('<span class="eyebrow">DEMONSTRATION COMPLETE</span><div class="success-mark">✓</div><h2>Purchase demonstration complete</h2><p>This demonstration took no payment, reserved no work and sent no order. This screen demonstrates the purchase confirmation experience.</p><p>In the live service, a verified order would show the actual seller, delivery status, support contact and artist settlement process.</p><button class="button" data-action="close-modal">Continue exploring <span></span></button>');}if(e.target.id==='viewing-form'){e.preventDefault();modal('<span class="eyebrow">REQUEST PREVIEW COMPLETE</span><h2>Viewing demonstration complete</h2><p>This demonstration did not send an inquiry or save your contact details. A live request would go only to a confirmed responsible recipient with your permission.</p><button class="button" data-action="close-modal">Back to the work <span></span></button>');}});
$('#preview-info').addEventListener('click',previewInfo);$('#concierge-launch').addEventListener('click',()=>openChat());$('#chat-close').addEventListener('click',closeChat);$('#modal-close').addEventListener('click',()=>$('#modal').close());$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});
$('#menu-button').addEventListener('click',()=>{const open=$('#mobile-nav').hidden;$('#mobile-nav').hidden=!open;$('#menu-button').setAttribute('aria-expanded',String(open));});
$('#region-button').addEventListener('click',()=>modal('<span class="eyebrow">TAOS REGION</span><h2>Taos region</h2><p>Our first region includes Taos, Ranchos de Taos, El Prado, Arroyo Seco and Taos Ski Valley, with selected day trips clearly identified.</p><div class="region-list"><button data-action="close-modal">Taos region <span>OUR FIRST PERSPECTIVE ✓</span></button><button disabled>Santa Fe & the High Road <span>FUTURE REGION</span></button><button disabled>The wider Southwest <span>FUTURE REGION</span></button></div>'));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#concierge').hidden){e.preventDefault();closeChat();}if(e.key==='Tab'&&!$('#concierge').hidden){const els=$$('button:not(:disabled),input,a[href]', $('#concierge')).filter(x=>!x.hidden),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',render);
try { const response=await fetch('data.json');if(!response.ok)throw new Error('Catalog could not load');data=await response.json();saved=saved.filter(id=>allIds().has(id)).slice(0,50);render(); }catch(error){$('#main').innerHTML='<div class="page-error"><h1>The catalog did not load</h1><p>Refresh the page to reload the prototype catalog.</p></div>';console.error(error);}

function compareWork(id) {
 if(!workFor(id))return;
 compared=compared.includes(id)?compared.filter(x=>x!==id):[...compared,id].slice(-2);
 if(compared.length===2){const ws=compared.map(workFor);modal(`<span class="eyebrow">COMPARISON, DEMO WORKS</span><h2>Demo work comparison</h2><div class="comparison-grid">${ws.map(w=>`<div><div class="comparison-image"><img src="assets/${w.image}" alt="Demo ${esc(w.title)}"></div><h3>${esc(w.title)}</h3><p>${esc(w.medium)}<br>${w.height} H × ${w.width} W in ,  example<br>Demo price ${money(w.price)}</p><a class="text-link" href="#/art/${w.id}" data-action="close-modal">Explore this study </a></div>`).join('')}</div><p class="small-print">These are demonstration studies. The comparison offers no physical artwork for sale.</p>`);}
 else toast('Choose one more work to compare');
 $$('[data-action="compare"]').forEach(b=>{const selected=compared.includes(b.dataset.id);b.setAttribute('aria-pressed',String(selected));b.textContent=selected?'Selected for comparison ✓':'Compare ＋';});
}
